import{c as r,Q as o,j as e,m as a}from"./chunks/framework.hhGiamYR.js";const h=JSON.parse('{"title":"畏惧与爱戴——马基雅维利最著名也最被误解的一句话","description":"","frontmatter":{"date":"2026-07-19T00:00:00.000Z","title":"畏惧与爱戴——马基雅维利最著名也最被误解的一句话"},"headers":[],"relativePath":"research/fear-and-love/index.md","filePath":"research/fear-and-love/index.md"}'),l={name:"research/fear-and-love/index.md"};function p(n,t,i,u,s,q){return o(),e("div",null,[...t[0]||(t[0]=[a('<p>&quot;被人畏惧比受人爱戴安全得多。&quot;这句话可能是马基雅维利所有言论中最著名的一句——也是最被断章取义的一句。</p><p>它常常被简化为一种冷酷的权术格言：&quot;让人怕你，别让人爱你。&quot;但这完全不是马基雅维利的意思。他的论证比这精确得多，也诚实得多。</p><h2 id="不是单选题-是迫不得已的二选一" tabindex="-1">不是单选题，是迫不得已的二选一 <a class="header-anchor" href="#不是单选题-是迫不得已的二选一" aria-label="Permalink to &quot;不是单选题，是迫不得已的二选一&quot;">​</a></h2><p>首先需要纠正一个普遍的误解：马基雅维利并不认为恐惧比爱更好——他认为<strong>两个都好，但如果只能选一个，选恐惧。</strong></p><blockquote><p>📖 <strong>原文</strong>：《君主论》第17章</p><p>究竟是受人爱戴比被人畏惧好呢，还是被人畏惧比受人爱戴好？回答是：最好两者兼备；但由于两者结合在一起难乎其难，所以，如果一个人必须有所取舍的话，那么，被人畏惧比受人爱戴安全得多。因为关于人类，一般可以这样说：他们是忘恩负义、容易变心的，是伪君子和假好人，是逃避危难、贪财好利的。</p><p>— <a href="https://niflhum.top/machiavelli-library/library/machiavelli/prince/prince-cn-full.md" target="_blank" rel="noreferrer">全文阅读</a></p></blockquote><p>注意这个论证结构。他不是说&quot;恐惧是好的&quot;——他说的是&quot;两者都好，但如果必须选，恐惧更可靠&quot;。为什么更可靠？不是因为恐惧本身更高尚，而<strong>因为人性</strong>。人们爱你是他们的选择，他们随时可以改变主意。人们怕你是你的选择，他们改变不了。</p><h2 id="博尔贾的残酷与佛罗伦萨的仁慈" tabindex="-1">博尔贾的残酷与佛罗伦萨的仁慈 <a class="header-anchor" href="#博尔贾的残酷与佛罗伦萨的仁慈" aria-label="Permalink to &quot;博尔贾的残酷与佛罗伦萨的仁慈&quot;">​</a></h2><p>马基雅维利用了两个极其具体的例子来支撑这个论点。</p><p>切萨雷·博尔贾在罗马涅用残酷手段镇压了割据的领主们——处决、消灭、&quot;让那个地区恢复了和平与信仰&quot;。他的残酷针对的是少数人，受益的是整个地区。</p><p>佛罗伦萨人为了避免残酷之名，放任皮斯托亚城内的派系仇杀继续蔓延。结果是整个城市被摧毁，死者远比博尔贾的残酷处决多得多。</p><blockquote><p>📖 <strong>原文</strong>：《君主论》第17章</p><p>切萨雷·博尔贾被人认为是残酷的，然而，他的残酷却重建了罗马涅，把它统一起来，使它恢复了和平与信仰。如果我们好好地考虑一下这一点，就会看到博尔贾要比佛罗伦萨人民仁慈得多，因为后者为了避免残酷之名而让皮斯托亚被摧毁。</p><p>— <a href="https://niflhum.top/machiavelli-library/library/machiavelli/prince/prince-cn-full.md" target="_blank" rel="noreferrer">全文阅读</a></p></blockquote><p>这个对比是马基雅维利式论证的精髓所在：他不辩论&quot;残酷是否道德&quot;，他直接比较<strong>后果</strong>。一种是少数人受罚、多数人受益的&quot;残酷&quot;，另一种是以仁慈之名坐视整个城市毁灭的&quot;仁慈&quot;。哪一个是真正的仁慈？哪一个是真正的残酷？他让你自己判断。</p><h2 id="最关键的约束-畏惧但不被憎恨" tabindex="-1">最关键的约束：畏惧但不被憎恨 <a class="header-anchor" href="#最关键的约束-畏惧但不被憎恨" aria-label="Permalink to &quot;最关键的约束：畏惧但不被憎恨&quot;">​</a></h2><p>这是整个论证中最常被遗忘、却被马基雅维利反复强调的底线：</p><blockquote><p>📖 <strong>原文</strong>：《君主论》第17章</p><p>君主应当以这样一种方式使人畏惧自己：即使不能获取爱戴，也要避免仇恨；因为被人畏惧同时又不为人所憎恨，二者可以很好地结合起来。只要他不触碰自己公民和臣民的财产、不染指他们的妻女，他就总是能够做到这一点。</p><p>人们忘记父亲之死比忘记遗产的丧失来得还要快。</p><p>— <a href="https://niflhum.top/machiavelli-library/library/machiavelli/prince/prince-cn-full.md" target="_blank" rel="noreferrer">全文阅读</a></p></blockquote><p>这一句&quot;人们忘记父亲之死比忘记遗产的丧失来得还要快&quot;——是整本《君主论》中最冷的一句话，也是最诚实的一句话。它不是在鼓励君主杀人，它是在警告君主：<strong>你杀一个人，他的儿子也许可以原谅你。你拿走他的财产，他一辈子不会忘记。</strong></p><p>所以&quot;畏惧但不被憎恨&quot;的可操作性在于：严酷地执法，但绝不掠夺私产。人们在法治的铁腕下可以活得很好——他们怕的是规则，不是你这个人。</p><p>这也解释了为什么马基雅维利在《君主论》第19章花了那么大的篇幅讨论罗马皇帝们的命运：那些被憎恨的皇帝都死了，那些被蔑视的皇帝也死了。连卓越如塞维鲁——既是狐狸又是狮子——虽然能够靠德能驾驭士兵，但他的残暴最终还是传给了儿子卡拉卡拉，&quot;全世界都开始痛恨他&quot;，于是他死了。关键在于<strong>被谁恨、被谁怕、被谁蔑视</strong>——这三者之间的精确平衡决定了统治的存亡。</p><h2 id="爱戴是别人的-畏惧是你自己的" tabindex="-1">爱戴是别人的，畏惧是你自己的 <a class="header-anchor" href="#爱戴是别人的-畏惧是你自己的" aria-label="Permalink to &quot;爱戴是别人的，畏惧是你自己的&quot;">​</a></h2><p>马基雅维利在《君主论》第17章的结尾给出了这个论证最深层的逻辑：</p><blockquote><p>📖 <strong>原文</strong>：《君主论》第17章</p><p>既然人们爱戴君主是出于他们自己的意愿，而畏惧君主则是出于君主的意愿；那么，一位明智的君主就应当立足于自己的意愿而不是他人的意愿，他只需设法避免仇恨。</p><p>— <a href="https://niflhum.top/machiavelli-library/library/machiavelli/prince/prince-cn-full.md" target="_blank" rel="noreferrer">全文阅读</a></p></blockquote><p>这句话是理解&quot;畏惧与爱戴&quot;问题的钥匙。它不是道德判断——它是<strong>控制力的判断</strong>。爱戴是由别人的心情决定的，你今天做对了他们会爱你，明天你做了一个不受欢迎的决定他们就可能背弃你。畏惧是由你自己的行动决定的——你有军队，你执法公正而严厉，你确立了不可动摇的声望，他们就怕你。<strong>&quot;立足于自己的意愿而不是他人的意愿&quot;</strong>——这就是区分一个能掌控局面的统治者和一个被民意裹挟的弱者的标准。</p><h2 id="《论李维》的补充-过度与平衡" tabindex="-1">《论李维》的补充：过度与平衡 <a class="header-anchor" href="#《论李维》的补充-过度与平衡" aria-label="Permalink to &quot;《论李维》的补充：过度与平衡&quot;">​</a></h2><p>如果说《君主论》是从统治者角度讨论畏惧与爱戴，《论李维》则提供了一个更微妙的军事视角。在讨论将帅与士兵的关系时，马基雅维利写道：</p><blockquote><p>人们被两种主要的情感所驱动：爱和恐惧。一个让人畏惧的将帅，和受人爱戴的将帅一样拥有权威；事实上，他通常被更忠实地追随和服从。然而，无论走哪条路都不重要，只要他有超群的英勇——因为像汉尼拔或西庇阿这样的人，非凡的英勇会掩盖他们追求过度被爱或过度被惧所犯的任何错误。然而这两种倾向都可能导致严重危害——想要被极度爱戴的人，哪怕偏离正道一点点，就会变得可鄙；想要被极度畏惧的人，如果走得太远一点点，就会招致仇恨。</p><p>— 《论李维》第一卷第21章，<a href="https://niflhum.top/machiavelli-library/library/machiavelli/discourses/book1/21-%E7%AC%AC%E4%BA%8C%E5%8D%81%E4%B8%80%E7%AB%A0.md" target="_blank" rel="noreferrer">全文阅读</a></p></blockquote><p>这里补充了一个重要的观点：<strong>技艺（virtù）可以弥补风格上的缺陷。</strong> 如果你真的足够强——像汉尼拔和西庇阿那样——那么你就算在爱和惧之间失了分寸，你的实力也能把你兜住。但马基雅维利紧接着就指出，连这两个人都付出了代价：西庇阿的军队在西班牙哗变（因为太过仁慈），汉尼拔的非人残酷也并非没有后患。所谓&quot;可以弥补&quot;，不等于&quot;没有后果&quot;。</p><h2 id="现代重新阅读" tabindex="-1">现代重新阅读 <a class="header-anchor" href="#现代重新阅读" aria-label="Permalink to &quot;现代重新阅读&quot;">​</a></h2><p>把&quot;畏惧与爱戴&quot;简化成&quot;统治者应该让人怕&quot;是对马基雅维利最粗暴的误读。他真正的意思是：</p><ol><li>最好两者都有，但现实不允许——因为你不可能让所有人都爱你，尤其在你必须做不得人心的决定时。</li><li>当必须选择时，选那个你<strong>能控制</strong>的。你能用规则、执法和声望让人怕你；你控制不了别人是否爱你。</li><li>但<strong>绝不能过线</strong>——不要碰人家的财产和妻女。一旦恐惧变成了仇恨，恐惧就从保护你的壁垒变成了悬在你头上的利剑。</li><li>如果你有超群的技艺，也许能弥补一些失衡——但我们大多数人没有汉尼拔的天赋。</li></ol><p>马基雅维利在这个问题上不是&quot;冷酷&quot;，他是<strong>清醒</strong>。他知道人是怎样的——忘恩负义、容易变心——所以他不把统治的基础建立在对他人的善良抱有期望之上。但与此同时，他划出了一条清晰的边界：不要变成暴君。你可以严厉，但不能贪婪；你可以让人怕你的法律，但不能让人恨你这个人。</p><p>这就是为什么&quot;畏惧优于爱戴&quot;不能脱离&quot;避免仇恨&quot;来单独引用。它们是同一个论证的两半，如同狮子和狐狸——分开来，每一半都是残缺的。</p><hr><p><em>尼科洛·马基雅维利，圣卡夏诺</em></p>',33)])])}const d=r(l,[["render",p]]);export{h as __pageData,d as default};
